<script setup lang="ts">import {computed,ref} from "vue";import {Download,FileText,Trash2,Upload} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Toolbar from "@/components/zs/Toolbar.vue";import SearchInput from "@/components/zs/SearchInput.vue";import ZButton from "@/components/zs/ZButton.vue";import SidePanel from "@/components/zs/SidePanel.vue";import Field from "@/components/zs/Field.vue";import ValidationMessage from "@/components/zs/ValidationMessage.vue";import {useAsyncData,useMutation} from "@/composables/useAsyncData";import {platformRepository} from "@/services/platform/repository";import {useCompanyStore} from "@/stores/company";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {PlatformDocument} from "@/types/platform";setPageMeta("Knowledge Documents","Tenant-protected attachments shared across ZavSync modules.");const company=useCompanyStore(),state=useAsyncData(()=>platformRepository.documents(company.activeCompanyId),{watch:[()=>company.activeCompanyId]}),q=ref(''),open=ref(false),type=ref('customer'),recordId=ref(''),category=ref('general'),file=ref<File|null>(null),rows=computed(()=>(state.data.value?.data??[]).filter(x=>x.original_filename.toLowerCase().includes(q.value.toLowerCase()))),columns:Column[]=[{key:'name',header:'Document'},{key:'owner',header:'Related record'},{key:'category',header:'Category'},{key:'size',header:'Size'},{key:'date',header:'Uploaded'},{key:'actions',header:''}];const upload=useMutation(()=>{if(!file.value)throw new Error('Select a file.');return platformRepository.uploadDocument(company.activeCompanyId,{type:type.value,id:recordId.value,category:category.value,file:file.value})});async function submit(){if(!await upload.run())return;showToast('Document uploaded','The private file is available to authorized company users.');open.value=false;file.value=null;recordId.value='';await state.refresh()}async function remove(row:PlatformDocument){await platformRepository.deleteDocument(company.activeCompanyId,row.id);showToast('Document deleted');await state.refresh()}const size=(bytes:number)=>bytes<1_048_576?`${Math.ceil(bytes/1024)} KB`:`${(bytes/1_048_576).toFixed(1)} MB`;</script>
<template><AppShell><PageHeader title="Knowledge Documents" description="Reusable private attachments with explicit company and related-record authorization"><template #actions><ZButton v-if="company.hasPermission('platform.documents.manage')" @click="open=true"><Upload class="size-4"/>Upload document</ZButton></template></PageHeader><ValidationMessage :message="state.error.value?.message"/><Panel><Toolbar><SearchInput v-model="q" placeholder="Search documents"/></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="950"><template #name="{row}:{row:PlatformDocument}"><div class="flex items-center gap-2"><FileText class="size-4 text-content-brand"/><div><p class="font-medium text-content">{{row.original_filename}}</p><p class="text-2xs text-content-muted">{{row.mime_type}}</p></div></div></template><template #owner="{row}:{row:PlatformDocument}"><p class="text-xs text-content">{{row.documentable_type.split('\\').pop()}}</p><p class="num text-2xs text-content-muted">{{row.documentable_id}}</p></template><template #category="{row}">{{row.category}}</template><template #size="{row}">{{size(row.size_bytes)}}</template><template #date="{row}">{{new Date(row.created_at).toLocaleDateString()}}</template><template #actions="{row}:{row:PlatformDocument}"><div class="flex justify-end gap-1"><ZButton variant="ghost" @click="platformRepository.downloadDocument(company.activeCompanyId,row.id,row.original_filename)"><Download class="size-4"/></ZButton><ZButton v-if="company.hasPermission('platform.documents.manage')" variant="ghost" @click="remove(row)"><Trash2 class="size-4"/></ZButton></div></template></DataTable></Panel><SidePanel :open="open" title="Upload document" description="PDF, Office, image, CSV and text files up to 10 MB." @close="open=false"><form class="space-y-4" @submit.prevent="submit"><label class="block"><span class="label-caps">Related record type</span><select v-model="type" class="field mt-1.5 w-full"><option v-for="item in ['customer','invoice','supplier','purchase_order','supplier_bill','inventory_item','employee','payroll_batch','crm_account','crm_lead','crm_deal']" :key="item">{{item}}</option></select></label><Field v-model="recordId" label="Related record ID" required/><Field v-model="category" label="Category"/><label class="block"><span class="label-caps">File</span><input type="file" class="field mt-1.5 w-full" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.xls,.xlsx,.csv,.txt" required @change="file=($event.target as HTMLInputElement).files?.[0]??null"/></label><ValidationMessage :message="upload.error.value?.message"/><ZButton type="submit" :disabled="upload.saving.value">{{upload.saving.value?'Uploading…':'Upload securely'}}</ZButton></form></SidePanel></AppShell></template>
